#[tauri::command]
fn get_config(state: tauri::State<'_, AppConfig>) -> String {
    state.api_key.clone()
}

struct AppCounter(Mutex<i32>);

#[tauri::command]
fn increment(state: tauri::State<'_, AppCounter>) {
    let mut count = state.0.lock().unwrap();
    *count += 1;
}
